def brand(v):
 return json.loads(json.dumps(v,ensure_ascii=False).replace('Bosch','Siemens').replace('bosch','Siemens'))

def make(i,sv):
 code=ITEMS[i];me,ms,ae,av,kind=DATA[i];meaning=ms if sv else me;action=av if sv else ae;v=brand(build_sv(code,meaning,action) if sv else build_en(code,meaning,action));causes=CAUSES[kind][1 if sv else 0]
 if sv:v.update({"title_tag":f"Siemens-tvättmaskin felkod {code}: säkra steg","meta_description":f"Visar Siemens-tvättmaskinen {code}? Läs verifierad betydelse, säkra yttre kontroller och när Siemens-service krävs.","h1":f"Vad betyder {code} på en Siemens-tvättmaskin?","description":meaning[0].upper()+meaning[1:]+".","quick_fix":action+" (cirka 5–30 minuter).","intro_html":f"<p>{meaning[0].upper()+meaning[1:]}.</p><p>{action}. Öppna inga paneler, gör inga elektriska mätningar och beställ inte reservdel från koden ensam.</p>","causes_json":[{"cause":x,"detail":"Detta är en möjlig orsak; exakt E‑Nr-manual och professionell diagnos avgör interna fel."} for x in causes],"steps_json":[{"step":1,"action":"Stoppa säkert","detail":"Stoppa programmet, vänta tills trumman står stilla och tvinga inte luckan."},{"step":2,"action":"Dokumentera kod och E‑Nr","detail":f"Fotografera hela {code}-visningen och anteckna E‑Nr, programfas och synliga symptom."},{"step":3,"action":"Gör endast rätt yttre kontroll","detail":action+". Följ manualen för exakt E‑Nr vid tömning eller filterrengöring."},{"step":4,"action":"Testa högst en gång","detail":"Testa endast efter korrigerad yttre orsak och aldrig vid läckage, bränd lukt, rök, onormal värme eller elskada."},{"step":5,"action":"Boka Siemens-service","detail":"Boka service om koden kvarstår eller återkommer. Demontera inget och mät inga interna delar."}],"when_to_call_technician_html":f"<p>Boka Siemens-service om {code} kvarstår efter säkra kontroller. Vid E23 ska kranen stängas omedelbart och maskinen inte användas.</p><p>Lucklås, värmare, sensorer, pumpar, ventiler, kablage och elektronik är inte användarreparationer.</p>","prevention_html":"<p>Följ installations-, last- och doseringsanvisningar och håll synliga slangar och användaråtkomliga filter rena enligt manualen.</p><p>Interna mekaniska och elektriska fel kan inte förebyggas genom demontering.</p>"})
 else:v.update({"title_tag":f"Siemens Washing Machine Error {code}: Safe Steps","meta_description":f"Siemens washer showing {code}? Read the verified meaning, safe external checks and when Siemens service is required.","h1":f"What Does {code} Mean on a Siemens Washing Machine?","description":meaning[0].upper()+meaning[1:]+".","quick_fix":action+" (about 5–30 minutes).","intro_html":f"<p>{meaning[0].upper()+meaning[1:]}.</p><p>{action}. Open no panels, make no electrical measurements and do not order a part from the code alone.</p>","causes_json":[{"cause":x,"detail":"This is a possible cause; the exact E-Nr manual and professional diagnosis determine internal faults."} for x in causes],"steps_json":[{"step":1,"action":"Stop safely","detail":"Stop the programme, wait for the drum to stop and do not force the door."},{"step":2,"action":"Record the code and E-Nr","detail":f"Photograph the complete {code} display and note the E-Nr, programme stage and visible symptoms."},{"step":3,"action":"Make only the correct external check","detail":action+". Follow the exact E-Nr manual when draining water or cleaning a filter."},{"step":4,"action":"Test no more than once","detail":"Test only after correcting an external cause, and never with leakage, burning smell, smoke, abnormal heat or electrical damage."},{"step":5,"action":"Arrange Siemens service","detail":"Request service if the code remains or returns. Dismantle nothing and measure no internal parts."}],"when_to_call_technician_html":f"<p>Arrange Siemens service if {code} remains after safe checks. For E23, close the tap immediately and do not use the washer.</p><p>Door locks, heaters, sensors, pumps, valves, wiring and electronics are not user repairs.</p>","prevention_html":"<p>Follow installation, load and detergent instructions and keep visible hoses and user-accessible filters clean as the manual specifies.</p><p>Internal mechanical and electrical faults cannot be prevented through dismantling.</p>"})
 v['parts_json']=[];assert len(v['title_tag'])<=70 and len(v['meta_description'])<=165;return v

