 b=json.loads((BASE_DIR/'data/backups/article_reviews/batch-031-siemens-e16-e23-before.json').read_text(encoding='utf-8'));rows={(r['article_id'],r['locale']):r for r in b['rows']};o={"batch":"031-siemens-e16-e23","status":"proposal_only_not_applied","article_ids":list(ITEMS),"sources":["https://www.siemens-home.bsh-group.com/ae/customer-service/support/troubleshooting/washing-machines/error-codes-symbols","https://www.siemens-home.bsh-group.com/ae/customer-service/support/troubleshooting/washing-machines/error-codes-e18-f18","https://www.siemens-home.bsh-group.com/uk/customer-service/support/washing-machine"],"translations":{}}
